          r, err := parseRateRaw(raw3)
          if err != nil {
            return nil, err
          }
          if rt.byDate[date] == nil {
            rt.byDate[date] = map[string]float64{}
          }
          rt.byDate[date][currency] = r
        }
      }
      delete(top, key)
    }
  }
  for _, key := range []string{"global", "Global"} {
    if raw, ok := top[key]; ok {
      if err := loadRateMap(rt, raw, true); err != nil {
        return nil, err
      }
      delete(top, key)
    }
