  Watermark        stateWatermarkOut      `json:"watermark"`
  SeenIDs          []string               `json:"seen_ids"`
  PendingPurchases []statePendingOut     `json:"pending_purchases"`
  OpenSessions     []stateOpenSessionOut  `json:"open_sessions"`
  RunIndex         int                    `json:"run_index"`
}

func loadState(path string) (*loadedState, error) {
  data, err := os.ReadFile(path)
  if err != nil {
    return nil, err
  }
  var sin stateFileIn
  if err := json.Unmarshal(data, &sin); err != nil {
    return nil, err
  }
  st := &loadedState{
    version:      sin.Version,
    seenIds:      map[string]bool{},
    runIndex:     sin.RunIndex,
    openSessions: map[string]carriedSession{},
  }
  if sin.Watermark.MaxTS != nil {
    t, err := parseTime(*sin.Watermark.MaxTS)
    if err != nil {
      return nil, fmt.Errorf("bad state watermark: %w", err)
    }
    st.hasMax = true
    st.maxTs = t
  }
  for _, id := range sin.SeenIDs {
    st.seenIds[id] = true
  }
  for _, p := range sin.PendingPurchases {
    t, err := parseTime(p.TS)
    if err != nil {
      return nil, fmt.Errorf("bad pending purchase ts: %w", err)
    }
    st.pending = append(st.pending, pendingEntry{id: p.ID, ts: t, user: p.User, usd: float64(p.USD), originRun: p.OriginRun})
  }
  for _, s := range sin.OpenSessions {
    last, err := parseTime(s.LastTS)
    if err != nil {
      return nil, fmt.Errorf("bad open session last_ts: %w", err)
    }
    start, err := parseTime(s.StartTS)
    if err != nil {
      return nil, fmt.Errorf("bad open session start_ts: %w", err)
    }
    st.openSessions[s.User] = carriedSession{user: s.User, lastTs: last, sessionIndex: s.SessionIndex, startTs: start}
  }
  st.carryInPending = len(st.pending)
  st.carryInOpenSessions = len(st.openSessions)
  return st, nil
}

func buildStateOut(currentMax time.Time, hasCurrentMax bool, st *loadedState, seenIds []string, pending []pendingEntry, openSessions []carriedSession, runIndex int) []byte {
  out := stateFileOut{Version: 1, SeenIDs: seenIDs, PendingPurchases: statePendingOutList(pending), OpenSessions: stateOpenSessionOutList(openSessions), RunIndex: runIndex}
  if hasCurrentMax {
    s := formatTS(currentMax)
    out.Watermark.MaxTS = &s
  } else if st != nil && st.hasMax {
    s := formatTS(st.maxTs)
    out.Watermark.MaxTS = &s
  }
  b, _ := json.MarshalIndent(out, "", "  ")
  b = append(b, '\n')
  return b
}

func statePendingOutList(pending []pendingEntry) []statePendingOut {
  out := make([]statePendingOut, 0, len(pending))
  for _, p := range pending {
    out = append(out, statePendingOut{ID: p.id, TS: formatTS(p.ts), User: p.user, USD: Money(p.usd), OriginRun: p.originRun})
  }
  return out
}

func stateOpenSessionOutList(sessions []carriedSession) []stateOpenSessionOut {
  out := make([]stateOpenSessionOut, 0, len(sessions))
  for _, s := range sessions {
    out = append(out, stateOpenSessionOut{User: s.user, LastTS: formatTS(s.lastTs), SessionIndex: s.sessionIndex, StartTS: formatTS(s.startTs)})
  }
  return out
}

func sortedSeenIDs(seen map[string]bool) []string {
  ids := make([]string, 0, len(seen))
  for id := range seen {
    ids = append(ids, id)
  }
  sort.Strings(ids)
  return ids
}

func sortedPending(pending []pendingEntry) []pendingEntry {
  out := append([]pendingEntry(nil), pending...)
  sort.SliceStable(out, func(i, j int) bool {
    if out[i].ts.Equal(out[j].ts) {
      return out[i].id < out[j].id
    }
    return out[i].ts.Before(out[j].ts)
  })
  return out
}

func sortedOpenSessions(m map[string]carriedSession) []carriedSession {
  out := make([]carriedSession, 0, len(m))
  for _, s := range m {
    out = append(out, s)
  }
  sort.SliceStable(out, func(i, j int) bool {
    if out[i].lastTs.Equal(out[j].lastTs) {
      return out[i].user < out[j].user
    }
    return out[i].lastTs.Before(out[j].lastTs)
  })
  return out
}

func sortedCarriedSessions(m map[string]carriedSession) []carriedSession {
  return sortedOpenSessions(m)
}
