func (p *processor) currentCutoff() string {
  if p.hasMax {
    return formatTS(p.maxTs.Add(-p.watermarkLag))
  }
  return ""
}

func (p *processor) updateMax(t time.Time) {
  if !p.hasMax || t.After(p.maxTs) {
    p.maxTs = t
    p.hasMax = true
  }
}

func (p *processor) processEvents(raws []rawEvent) ([]*Event, []Reject, []auditRecord) {
  var accepted []*Event
  var rejects []Reject
  var audits []auditRecord
  for _, raw := range raws {
    ctx := newContext(raw)
    ev, invalidReason := parseEvent(ctx, p.rt)
    if ev == nil {
      rec := auditRecord{Bucket: "invalid", Reason: invalidReason, Raw: ctx}
      rejects = append(rejects, Reject{Bucket: 1, Reason: invalidReason, Event: ctx.Raw})
      audits = append(audits, rec)
      continue
    }
    if p.seenIds[ev.ID] {
      rec := auditRecord{Bucket: "duplicate", Reason: "cross_run", Raw: ctx}
      rejects = append(rejects, Reject{Bucket: 2, Reason: "cross_run", Event: ctx.Raw})
      audits = append(audits, rec)
      continue
    }
    if p.sameRunSeen[ev.ID] {
      rec := auditRecord{Bucket: "duplicate", Reason: "same_run", Raw: ctx}
      rejects = append(rejects, Reject{Bucket: 2, Reason: "same_run", Event: ctx.Raw})
      audits = append(audits, rec)
      continue
    }
    cutoff := p.currentCutoff()
    if p.hasMax && ev.TS.Before(p.maxTs.Add(-p.watermarkLag)) {
      rec := auditRecord{Bucket: "late", Cutoff: cutoff, Raw: ctx}
      rejects = append(rejects, Reject{Bucket: 3, Reason: "late", Event: ctx.Raw})
      audits = append(audits, rec)
      continue
    }
    p.sameRunSeen[ev.ID] = true
    p.updateMax(ev.TS)
    acceptedEvent, audit := p.acceptEvent(ctx, ev)
    accepted = append(accepted, acceptedEvent)
    audits = append(audits, audit)
  }
  return accepted, rejects, audits
}

func (p *processor) acceptEvent(ctx *eventContext, ev *Event) (*Event, auditRecord) {
  p.handleSession(ev)
  rec := auditRecord{Bucket: "accepted", USD: ev.USD, SessionIndex: ev.sessionIndex, ResolvedAgainst: nil, Raw: ctx}
  switch ev.Type {
  case "purchase":
    pe := pendingEntry{id: ev.ID, ts: ev.TS, user: ev.UserID, usd: ev.USD, originRun: p.runIndex + 1}
    p.pending = append(p.pending, pe)
    p.pendingByID[ev.ID] = &p.pending[len(p.pending)-1]
  case "refund":
    pe := pendingEntry{id: ev.ID, ts: ev.TS, user: ev.UserID, usd: ev.USD, originRun: p.runIndex + 1}
    p.pending = append(p.pending, pe)
    p.pendingByID[ev.ID] = &p.pending[len(p.pending)-1]
  case "chargeback":
    resolved := p.resolveChargeback(ev)
    if resolved == "" {
      rec.Bucket = "unresolved_chargeback"
      rec.RefID = ev.RefID
      p.stats.Anomalies? // placeholder
    } else {
      rec.ResolvedAgainst = &resolved
    }
  }
  return ev, rec
}
